inline DrawSnapshot native_lamp_normalized(const DrawSnapshot& g){if(g.fvf!=0x102||g.stride!=20)return g;auto copy=g;if(g.vertex_bytes.size()!=uint64_t(g.vertex_count)*20)return {};copy.fvf=0x112;copy.stride=32;copy.vertex_byte_offset=(uint64_t(g.base_vertex)+g.min_index)*32;copy.vertex_bytes.assign(uint64_t(g.vertex_count)*32,0);for(unsigned i=0;i<g.vertex_count;++i){std::memcpy(copy.vertex_bytes.data()+i*32,g.vertex_bytes.data()+i*20,12);std::memcpy(copy.vertex_bytes.data()+i*32+24,g.vertex_bytes.data()+i*20+12,8);}return copy;}
inline bool exact_native_lamp(const DrawSnapshot& g,unsigned vertices,unsigned triangles,const char* geometry,const char* positionUv){if(g.vertex_count!=vertices||g.primitive_count!=triangles||NativeLampContinuity::topology(g).empty())return false;auto n=native_lamp_normalized(g);if(position_uv_corner_sha(n)!=positionUv)return false;if(n.fvf==0x112){auto copy=n;copy.fvf=0x152;copy.stride=36;copy.base_vertex=0;copy.vertex_byte_offset=uint64_t(g.min_index)*36;copy.vertex_bytes.assign(uint64_t(g.vertex_count)*36,0);for(unsigned i=0;i<g.vertex_count;++i)std::memcpy(copy.vertex_bytes.data()+i*36,n.vertex_bytes.data()+i*32,12);n=std::move(copy);}auto faces=vehicle_face_hashes(n);if(faces.size()!=g.primitive_count)return false;std::sort(faces.begin(),faces.end());std::string joined;for(const auto& f:faces)joined+=f;return sha256_bytes(joined.data(),joined.size())==geometry;}
inline ReflectionIdentity owned_off_lamp_identity(const ReflectionSnapshot& s,const FleetOffLampProfile& p,bool owner,bool topology,uint64_t reset){ReflectionIdentity id;id.vehicle=p.family;id.reason="owned_off_lamp_dependencies_rejected";const auto* g=s.geometry;if(!owner||!topology||!g||!g->supported_build||g->vertex_count!=p.vertices||g->primitive_count!=p.triangles||NativeLampContinuity::topology(*g).empty()||g->reset_generation!=reset||s.requested_mode!=4||!s.live_race_verified||!s.race_generation||!s.owner_lifetime||!s.stock_coordinate_policy||!s.native_states_complete||!s.native_matches_effective||!s.texture_matrix_known||!s.textures_are_2d||!s.textures[0]||!s.textures[1]||!s.texture_generations[0]||!s.texture_generations[1]||s.render_states!=std::array<DWORD,4>{FALSE,FALSE,TRUE,FALSE}||s.stages[0]!=std::array<DWORD,8>{D3DTOP_MODULATE,D3DTA_TEXTURE,D3DTA_DIFFUSE,D3DTOP_MODULATE,D3DTA_TEXTURE,D3DTA_DIFFUSE,0,0}||s.stages[1]!=std::array<DWORD,8>{D3DTOP_MODULATEALPHA_ADDCOLOR,D3DTA_CURRENT,D3DTA_TEXTURE,D3DTOP_MODULATE,D3DTA_CURRENT,D3DTA_TEXTURE,D3DTSS_TCI_CAMERASPACENORMAL,D3DTTFF_COUNT2})return id;id.accepted=true;id.source_material_authority=true;id.reason="current_family_owned_off_clone_with_healthy_source_reference";id.geometry_sha256=p.geometry;id.current_geometry_sha256=reflection_geometry_sha(*g);id.uv_topology_sha256=NativeLampContinuity::topology(*g);return id;}
